let reviewPrivateTargetPlan=null;
const reviewPrivateTargetJobs=new Set();
function reviewPrivateTargetStatus(n){const r=n.targetReceipts?.at(-1);return r?`上次服务私人回执：目标 v${r.sourceVersion}${r.sourceVersion===n.version?'':'；当前修订尚未保存'}`:'本人行动档案中，目标服务尚未保存'}
async function reviewOpenPrivateTarget(nid){
 const context=reviewContext(),ownerId=context.ownerId,n=S.nodes.find(n=>n.id===nid);if(!S.user?.reviewService||!n)return;
 try{if(n.ownership!=='personal'||n.visibility!=='private')throw Error('这里保存私人目标；公开或归属变更需要另行核对。');if(!reviewReady||reviewClient.snapshot().ownerId!==ownerId)throw Error('请先连接本人服务账号。');const fingerprint=reviewSharedTarget(n);if(!save())throw Error('本机保存未完成，原目标保留。');await reviewFlush();const result=await reviewKnowledgeRequest('/api/review-private-targets',{context});const current=S.nodes.find(n=>n.id===nid);if(!reviewContextCurrent(context)||!current||reviewSharedTarget(current)!==fingerprint)throw Error('目标或账号已有变化，请重新核对。');
  reviewPrivateTargetPlan={context,ownerId,nid,fingerprint,sourceVersion:n.version,old:result.current.find(r=>r.originId===nid)||null};const plan=reviewPrivateTargetPlan;
  modal(`<h2>保存私人知识目标</h2><p class="small muted">只有本人账号可读，持有者由服务账号确定；本次保存不会公开或捐赠目标。</p><h3 style="margin-top:18px">${esc(n.title)} · 目标 v${n.version}</h3><p class="pre">${esc(n.goal)}</p><p class="pre small">五分钟起步：${esc(n.five)}</p><p class="small muted">${esc(n.domain)} / ${esc(n.branch)}</p>${plan.old?`<details class="saved-notes"><summary>核对服务当前目标</summary><h3>${esc(plan.old.node.title)}</h3><p class="pre">${esc(plan.old.node.goal)}</p><p class="pre small">${esc(plan.old.node.five)}</p></details>`:''}<form id="review-private-target-form" class="stack"><p id="review-private-target-error" class="error" role="alert"></p><button class="primary">确认私人保存目标</button></form><div class="row actions">${btn('重新核对服务目标','review-private-target:'+nid,'ghost')}${btn('稍后再做','dialog-close','ghost')}</div>`,'','私人目标保存');document.getElementById('review-private-target-form').addEventListener('submit',ev=>{ev.preventDefault();reviewCommitPrivateTarget(plan,ev.target)});
 }catch(error){if(reviewContextCurrent(context))modal(`<h2>私人目标尚未保存到服务</h2><p>${esc(reviewIsNetworkError(error)?'连接未完成，目标与版本保留在本人档案。':error.message)}</p><div class="row actions">${btn('重新核对','review-private-target:'+nid)}${btn('保留目标，稍后再做','dialog-close','ghost')}</div>`,'','私人目标服务状态')}
}
async function reviewCommitPrivateTarget(plan,form){
 const key=JSON.stringify([plan.ownerId,plan.context.generation,plan.nid]);if(reviewPrivateTargetJobs.has(key))return;reviewPrivateTargetJobs.add(key);const button=form.querySelector('button');button.disabled=true;
 try{const n=S.nodes.find(n=>n.id===plan.nid);if(!reviewContextCurrent(plan.context)||!n||reviewSharedTarget(n)!==plan.fingerprint)throw Error('目标或账号已经变化，请重新核对。');if(!save())throw Error('本机保存未完成，原目标保留。');await reviewFlush();if(!reviewContextCurrent(plan.context)||reviewSharedTarget(n)!==plan.fingerprint)throw Error('提交期间目标有变化，请重新核对。');
  const result=await reviewKnowledgeRequest('/api/review-private-targets',{context:plan.context,body:{nodeId:n.id,sourceVersion:n.version},headers:{'If-Match':reviewClient.snapshot().revision,...(plan.old?{'If-Target-Match':plan.old.revision}:{})}});
  if(!reviewContextCurrent(plan.context))return;const b=result.binding;if(b?.ownerId!==plan.ownerId||b.target?.id!==n.id||b.target.version!==plan.sourceVersion||b.ref?.visibility!=='private')throw Error('私人目标回执不一致，请重新核对。');
  const current=S.nodes.find(n=>n.id===plan.nid);if(current){if(!Array.isArray(current.targetReceipts))current.targetReceipts=[];if(!current.targetReceipts.some(r=>r.sourceHash===b.sourceHash))current.targetReceipts.push({treeId:b.ref.treeId,nodeId:b.ref.nodeId,version:b.ref.targetVersion,sourceVersion:b.ref.sourceVersion,sourceHash:b.sourceHash,at:Date.now()});save()}
  if(document.getElementById('review-private-target-form')===form)closeModal();render(false);toast('私人目标已由本人服务账号确认保存，旧版本保留。');
 }catch(error){if(reviewContextCurrent(plan.context)&&document.getElementById('review-private-target-form')===form)document.getElementById('review-private-target-error').textContent=reviewIsNetworkError(error)?'连接未完成，原目标与版本保留，请重新核对。':error.message}
 finally{reviewPrivateTargetJobs.delete(key);button.disabled=false}
}
